function esc(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}

function validate(rows){const allowed=new Set(["food_drinks","groceries","dry_goods","bookshop","hardware","garments_clothes_footwear","jewelry","electronics_bcfe08f"]);if(!Array.isArray(rows)||rows.length>10000)throw Error("Invalid catalogue size");const seen=new Set();return rows.map(r=>{if(!r||typeof r.id!=="string"||!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(r.id)||seen.has(r.id)||!allowed.has(r.category)||typeof r.name!=="string"||!r.name.trim()||r.name.length>250||typeof r.category_name!=="string"||!r.category_name.trim()||r.category_name.length>200||!["available","out_of_stock","check_live"].includes(r.availability)||![r.regular_price_kes,r.current_price_kes].every(p=>p===null||(typeof p==="number"&&Number.isFinite(p)&&p>0)))throw Error("Invalid catalogue row");seen.add(r.id);return {id:r.id,name:r.name,category:r.category,category_name:r.category_name,availability:r.availability,regular_price_kes:r.regular_price_kes,current_price_kes:r.current_price_kes};}).sort((a,b)=>a.id.localeCompare(b.id));}


const STYLE="*{box-sizing:border-box}body{margin:0;background:#f4f6fa;color:#07152f;font:15px system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif}a{color:inherit;text-decoration:none}a:focus-visible,button:focus-visible{outline:3px solid #ff7800;outline-offset:3px}header{background:#07152f;color:white;border-bottom:4px solid #ff7800}.nav{max-width:1200px;margin:auto;padding:16px 24px;display:flex;align-items:center;gap:16px;flex-wrap:wrap}.brand{display:flex;align-items:center;gap:12px;font-weight:850;letter-spacing:.3px}.brand img{width:54px;height:54px;object-fit:contain;background:white;border-radius:9px}.brand small{display:block;color:#d1d9e7;font-weight:400;font-size:12px}.navlinks{margin-left:auto;display:flex;gap:14px;align-items:center;flex-wrap:wrap;font-weight:650}.navlinks a:hover{text-decoration:underline}main{max-width:1200px;margin:auto;padding:24px}.hero{background:linear-gradient(115deg,#07152f,#17385f);color:white;border-radius:22px;padding:36px;margin-bottom:24px}.hero h1{margin:0 0 8px;font-size:clamp(28px,4vw,44px);letter-spacing:-1px}.hero p{margin:0;color:#e0e7f2}.eyebrow{color:#ffab60;font-weight:800;font-size:12px;letter-spacing:1.5px;text-transform:uppercase}.crumb{color:#52627a;font-size:13px;margin-bottom:16px}.crumb a{text-decoration:underline}.section-title{font-size:23px;margin:26px 0 12px}.chips{display:flex;gap:9px;flex-wrap:wrap;margin:0 0 18px}.chip{background:white;border:1px solid #dce3ed;border-radius:24px;padding:9px 15px;font-weight:650}.chip:hover{border-color:#ff7800;color:#b34d00}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:17px}.card{display:flex;flex-direction:column;background:white;border:1px solid #e1e6ee;border-radius:16px;overflow:hidden;box-shadow:0 4px 18px #07152f0b;min-width:0}.card:hover{box-shadow:0 8px 26px #07152f1a}.photo{aspect-ratio:1/1;background:#f5f7fa;display:grid;place-items:center;overflow:hidden;color:#66748a;text-align:center;padding:8px}.photo img{width:100%;height:100%;object-fit:contain;min-height:0}.cardbody{padding:15px;display:flex;flex-direction:column;gap:8px;flex:1}.tag{font-size:11px;text-transform:uppercase;color:#68778d;font-weight:800;letter-spacing:.35px}.card h2{font-size:17px;margin:0;line-height:1.25}.price{font-weight:850;color:#d85c00;font-size:19px}.muted{color:#596a80;font-size:13px}.btn{display:inline-flex;align-items:center;justify-content:center;border-radius:9px;background:#ff7800;color:#07152f;font-weight:800;padding:11px 15px;border:0;cursor:pointer;text-align:center}.btn:hover{background:#ff9a38}.card .btn{margin-top:auto}.detail{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:28px;background:white;border:1px solid #e1e6ee;border-radius:20px;padding:24px}.detail h1{margin:8px 0;font-size:32px}.detail .photo{border-radius:14px}.gallery{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.thumb{width:68px;height:68px;border:1px solid #d8e1ed;border-radius:9px;background:white;cursor:pointer;padding:4px}.thumb img{width:100%;height:100%;object-fit:contain}.thumb[aria-pressed=true],.variant[aria-pressed=true]{border:2px solid #ff7800;background:#fff5e9}.variants{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.variant{border:1px solid #d8e1ed;border-radius:9px;background:white;padding:8px 12px;cursor:pointer;color:#07152f;font:inherit;display:flex;align-items:center;gap:8px;text-align:left}.variant img{width:44px;height:44px;object-fit:contain}.variant small{display:block;color:#596a80}.variant:disabled{opacity:.5;cursor:not-allowed}.desc{white-space:pre-line;line-height:1.65;color:#33465d}.notice{padding:12px;background:#f2f6fb;border-radius:9px;color:#52627a;font-size:13px;margin:14px 0}.stock{color:#16734a;font-weight:650}.search{width:min(100%,440px);padding:12px 14px;border:1px solid #d5dfea;border-radius:10px;font:inherit;background:white;margin-bottom:18px}footer{background:#07152f;color:#dbe4ef;padding:24px;text-align:center;margin-top:28px}footer a{color:white;text-decoration:underline}[hidden]{display:none!important}@media(max-width:900px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.detail{gap:18px;padding:16px}}@media(max-width:580px){main{padding:15px}.nav{padding:12px 15px}.navlinks{margin-left:0;font-size:13px}.hero{padding:23px}.grid{gap:10px}.cardbody{padding:11px}.card h2{font-size:15px}.price{font-size:17px}.detail{grid-template-columns:1fr}.detail h1{font-size:26px}.brand img{width:44px;height:44px}}";
function media(path,staging=false){if(staging||typeof path!=="string"||!/^[0-9a-f-]{36}\/[A-Za-z0-9][A-Za-z0-9_.-]*\.(?:jpe?g|png|webp|avif|gif)$/i.test(path)||path.includes(".."))return "";return "https://dzdciuqkqixwutvtfotj.supabase.co/storage/v1/object/public/seller-product-media/"+path.split("/").map(encodeURIComponent).join("/");}

function build(rows,origin,staging=false){if(origin!==(staging?"https://staging.invalid":"https://leogo.co.ke"))throw Error("Unexpected origin");const source=new Map(rows.map(r=>[r.id,r]));rows=validate(rows).map(r=>({...r,image_path:source.get(r.id).image_path, gallery:Array.isArray(source.get(r.id).gallery)?source.get(r.id).gallery.slice(0,8):[],variants:Array.isArray(source.get(r.id).variants)?source.get(r.id).variants.filter(v=>v&&typeof v.name==="string").slice(0,100):[]}));const files={},root="/seo-catalogue/",prod=r=>root+"products/"+r.id+"/",cat=c=>root+"categories/"+c+"/",groups=new Map();for(const r of rows){if(!groups.has(r.category))groups.set(r.category,[]);groups.get(r.category).push(r);}const label=n=>String(n).toLowerCase().replace(/\b\w/g,c=>c.toUpperCase()).replace("Footwares","Footwear");const page=(title,path,body,extra="")=>`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#07152f"><title>${esc(title)} | LEOGO Digital Market</title><meta name="description" content="${esc(title)} — explore approved products on LEOGO Digital Market. Shop online in Kenya."><link rel="canonical" href="${esc(origin+path)}">${staging?'<meta name="robots" content="noindex,nofollow">':'<link rel="icon" href="/assets/images/leogo-official-logo.jpg">'}<link rel="stylesheet" href="${root}catalogue.css"></head><body><header><nav class="nav"><a class="brand" href="${staging?root:"/"}">${staging?"":'<img src="/assets/images/leogo-official-logo.jpg" alt="LEOGO logo">'}<span>LEOGO DIGITAL MARKET<small>Everything You Need. Delivered.</small></span></a><div class="navlinks"><a href="${root}">Shop catalogue</a>${staging?"":'<a href="/#live-product-catalogue">Marketplace</a><a href="/#customer-cart">My cart</a>'}</div></nav></header><main>${body}</main><footer>LEOGO DIGITAL MARKET · Everything you need. Delivered.${staging?" · Staging only":' · <a href="/">Visit customer website</a>'}</footer>${extra}</body></html>\n`;const put=(path,html)=>files[path.slice(1)+"index.html"]=html;const photo=(r,path=r.image_path,thumbnail=false)=>{const full=media(path,staging);const url=thumbnail&&/-opt\.webp$/.test(path||'')?media(path.replace(/-opt\.webp$/,'-thumb.webp'),staging):full;return url?`<img src="${esc(url)}" ${thumbnail&&url!==full?`data-full-image="${esc(full)}"`:""} alt="${esc(r.name)}" loading="lazy" decoding="async" width="480" height="480">`:"<span>Product photo unavailable</span>";};const chips=()=>'<nav class="chips" aria-label="Categories"><a class="chip" href="'+root+'">All products</a>'+[...groups].map(([c,rs])=>`<a class="chip" href="${cat(c)}">${esc(label(rs[0].category_name))} (${rs.length})</a>`).join("")+'</nav>';const cards=rs=>`<div class="grid">${rs.map(r=>`<article class="card" data-catalogue-card="${r.id}" data-search="${esc(r.name+" "+r.category_name)}"><a class="photo" href="${prod(r)}">${photo(r,r.image_path,true)}</a><div class="cardbody"><span class="tag">${esc(label(r.category_name))}</span><h2><a href="${prod(r)}">${esc(r.name)}</a></h2><div class="price" data-card-price>Check price</div><span class="muted" data-card-stock>${r.variants.length?`${r.variants.length} options`:"View product details"}</span><a class="btn" href="${prod(r)}">View product</a></div></article>`).join("")}</div>`;const script=staging?"":`<script src="${root}live.js" defer></script>`;put(root,page("Shop by category",root,`<section class="hero"><span class="eyebrow">LEOGO Marketplace</span><h1>Shop by category</h1><p>Discover products from approved LEOGO sellers. Browse, compare and shop with confidence.</p></section>${chips()}<h2 class="section-title">All products</h2><input class="search" id="catalogue-search" type="search" placeholder="Search products or categories" aria-label="Search products">${cards(rows)}<p id="empty-results" hidden>No products match your search.</p>`,script));for(const [c,rs] of groups)put(cat(c),page(label(rs[0].category_name),cat(c),`<div class="crumb"><a href="${root}">All products</a> / ${esc(label(rs[0].category_name))}</div><section class="hero"><span class="eyebrow">Shop LEOGO</span><h1>${esc(label(rs[0].category_name))}</h1><p>${rs.length} approved ${rs.length===1?"product":"products"} in this category.</p></section>${chips()}${cards(rs)}`,script));for(const r of rows){const photos=[...new Set([r.image_path,...r.gallery].filter(x=>media(x,staging)))];const shop=staging?"":`<p><a class="btn" id="shop-link" hidden href="/?product_id=${encodeURIComponent(r.id)}&amp;product_category=${encodeURIComponent(r.category)}">View product and shop on LEOGO</a></p>`;put(prod(r),page(r.name,prod(r),`<div class="crumb"><a href="${root}">All products</a> / <a href="${cat(r.category)}">${esc(label(r.category_name))}</a></div><article class="detail" data-product-id="${r.id}"><div><div class="photo" id="main-photo">${photo(r)}</div><div class="gallery" id="gallery">${photos.map((p,i)=>`<button class="thumb" type="button" data-photo="${esc(media(p,staging))}" aria-label="View photo ${i+1}" aria-pressed="${i===0}">${photo(r,p)}</button>`).join("")}</div></div><div><span class="tag">${esc(label(r.category_name))}</span><h1>${esc(r.name)}</h1><p class="price" id="live-status" role="status">Check current price and availability in the marketplace.</p><div id="variant-area"${r.variants.length?"":" hidden"}><h2 class="section-title">Choose an option</h2><div class="variants" id="variants">${r.variants.map(v=>`<span class="chip">${esc(v.name.slice(0,200))}</span>`).join("")}</div><p class="muted" id="variant-note">Confirm your selected option in the marketplace.</p></div><p class="desc" id="description"></p>${shop}<div class="notice">Delivery, Market Day offers and final checkout prices are confirmed in the LEOGO marketplace.</div></div></article>`,script));}const paths=["/",root,...[...groups.keys()].map(cat),...rows.map(prod)];files["sitemap.xml"]='<?xml version="1.0" encoding="UTF-8"?>\n<!-- LEOGO SEO generator v2 -->\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+paths.map(p=>"  <url><loc>"+esc(origin+p)+"</loc></url>").join("\n")+"\n</urlset>\n";files["seo-catalogue/.generated"]="LEOGO SEO generator v2\n";files["seo-catalogue/catalogue.css"]=STYLE;return files;}

function liveSource(key){if(!/^sb_publishable_[A-Za-z0-9_-]+$/.test(key))throw Error("Expected existing public frontend key");return `(${browser.toString()})(${JSON.stringify(key)},${media.toString()});\n`;}

function browser(key,media){'use strict';document.addEventListener?.('error',event=>{const img=event.target;if(img?.tagName==='IMG'&&img.dataset.fullImage&&img.src!==img.dataset.fullImage)img.src=img.dataset.fullImage;},true);const el=document.querySelector('[data-product-id]'),status=document.getElementById('live-status'),link=document.getElementById('shop-link'),cards=[...document.querySelectorAll('[data-catalogue-card]')],search=document.getElementById('catalogue-search');const money=n=>typeof n==='number'&&Number.isFinite(n)&&n>0?'KSh '+n.toLocaleString('en-KE',{maximumFractionDigits:2}):null;const showPhoto=url=>{const box=document.getElementById('main-photo');if(!box||!url)return;let img=box.querySelector('img');if(!img){img=document.createElement('img');img.alt=document.querySelector('h1')?.textContent||'Product';box.replaceChildren(img);}img.src=url;};document.querySelectorAll('[data-photo]').forEach(b=>b.addEventListener('click',()=>{const url=b.dataset.photo;if(!url.startsWith('https://dzdciuqkqixwutvtfotj.supabase.co/storage/v1/object/public/seller-product-media/'))return;showPhoto(url);document.querySelectorAll('[data-photo]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));}));if(search)search.addEventListener('input',()=>{const q=search.value.trim().toLowerCase();cards.forEach(c=>c.hidden=!c.dataset.search.toLowerCase().includes(q)||c.dataset.ineligible==='true');const empty=document.getElementById('empty-results');if(empty)empty.hidden=cards.some(c=>!c.hidden);});if(!el&&!cards.length)return;fetch('https://dzdciuqkqixwutvtfotj.supabase.co/rest/v1/rpc/seo_branded_catalogue_v3',{method:'POST',headers:{apikey:key,'Content-Type':'application/json'},body:'{}',cache:'no-store'}).then(r=>{if(!r.ok)throw Error('unavailable');return r.json();}).then(rows=>{if(!Array.isArray(rows))throw Error('unavailable');const map=new Map(rows.map(p=>[p.id,p]));for(const card of cards){const p=map.get(card.dataset.catalogueCard);if(!p){card.hidden=true;card.dataset.ineligible='true';continue;}const vs=Array.isArray(p.variants)?p.variants:[],prices=vs.map(v=>v.price_kes).filter(n=>money(n));const amount=money(p.current_price_kes)||(prices.length?(Math.min(...prices)===Math.max(...prices)?money(prices[0]):'From '+money(Math.min(...prices))):'Select options to see price');card.querySelector('[data-card-price]').textContent=amount;card.querySelector('[data-card-stock]').textContent=p.availability==='out_of_stock'?'Out of stock':vs.length?vs.length+' options':p.availability==='available'?'Available':'Check availability';}if(!el||!status||!link)return;const p=map.get(el.dataset.productId);if(!p){status.textContent='This listing is no longer available.';el.querySelectorAll('a,button').forEach(a=>a.hidden=true);document.querySelector('h1').textContent='Listing unavailable';document.title='Listing unavailable | LEOGO';const meta=document.createElement('meta');meta.name='robots';meta.content='noindex';document.head.append(meta);return;}const description=document.getElementById('description');if(description)description.textContent=typeof p.description==='string'?p.description:'';const vs=Array.isArray(p.variants)?p.variants:[],area=document.getElementById('variant-area'),box=document.getElementById('variants');const stock=p.availability==='out_of_stock'?'Out of stock':p.availability==='available'?'Available':'Check availability';status.textContent=(money(p.current_price_kes)||'Select options to see price')+' · '+stock;link.href='/?product_id='+encodeURIComponent(p.id)+'&product_category='+encodeURIComponent(p.category);link.hidden=false;if(area&&box){area.hidden=!vs.length;box.replaceChildren();for(const v of vs){if(typeof v.name!=='string')continue;const b=document.createElement('button');b.type='button';b.className='variant';b.disabled=v.available!==true;b.setAttribute('aria-pressed','false');const url=media(v.image_path);if(url){const im=document.createElement('img');im.src=url;im.alt='';b.append(im);}const span=document.createElement('span');span.textContent=v.name;const price=document.createElement('small');price.textContent=(money(v.price_kes)||'Check price')+(v.available?'':' · Out of stock');span.append(price);b.append(span);b.addEventListener('click',()=>{box.querySelectorAll('button').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));status.textContent=(money(v.price_kes)||'Check price')+' · '+v.name;const note=document.getElementById('variant-note');if(note)note.textContent='Selected '+v.name+'. Choose this option again in the marketplace to complete your order.';if(url)showPhoto(url);});box.append(b);}}}).catch(()=>{if(status)status.textContent='Live price unavailable. Visit the marketplace to check current listings.';});}
